test('vatSummary with mixed invoice statuses', () => {
  const issued = createAndIssueInvoice('C-001', '2026-10-01', 'DES-HOUR', 1);
  const partially = createAndIssueInvoice('C-001', '2026-10-02', 'DES-HOUR', 1);
  const paymentResult = recordPayment(partially, { amount: 1000, date: '2026-10-08' });
  assert.equal(paymentResult.ok, true);
  const paid = createAndIssueInvoice('C-001', '2026-10-03', 'DES-HOUR', 1);
  const totals = invoiceTotals(paid);
  const paidResult = recordPayment(paid, { amount: totals.total, date: '2026-10-08' });
  assert.equal(paidResult.ok, true);

  const result = vatSummary([issued, paymentResult.value, paidResult.value]);

  assert.equal(result.length, 1);
  assert.equal(result[0].rate, 21);
  const line1 = issued.lines[0];
  const line2 = paymentResult.value.lines[0];
  const line3 = paidResult.value.lines[0];
  const expectedBase = (lineTotal(line1) - lineDiscount(line1)) +
                       (lineTotal(line2) - lineDiscount(line2)) +
                       (lineTotal(line3) - lineDiscount(line3));
  const expectedVat = lineVAT(line1) + lineVAT(line2) + lineVAT(line3);
  assert.equal(result[0].base, expectedBase);
  assert.equal(result[0].vat, expectedVat);
});

