  const invoice = createAndIssueInvoice('C-001', '2026-09-01', 'DES-HOUR', 1, 'NET14');

  const beforeDueResult = overdueInvoices([invoice], '2026-09-14');
  const onDueResult = overdueInvoices([invoice], '2026-09-15');
