1	import { daysBetween } from './dates.js';
2	import { balanceDue } from './payments.js';
3	import { lineTotal, lineDiscount, lineVAT } from './invoices.js';
4	import { roundCents } from './money.js';
5	
6	/**
7	 * Get all invoices that are overdue as of a given date.
8	 * @param {Array<{ number: string, customerId: string, status: string, dueDate: string, lines: Array, payments?: Array<{ amount: number, date: string }> }>} invoices
9	 * @param {string} asOf - YYYY-MM-DD format, cutoff date
10	 * @returns {Array<{ number: string, customerId: string, dueDate: string, daysOverdue: number, due: number }>} sorted by daysOverdue descending (most overdue first)
11	 */
12	export function overdueInvoices(invoices, asOf) {
13	  return invoices
14	    .filter((inv) => (inv.status === 'issued' || inv.status === 'partially_paid'))
15	    .filter((inv) => inv.dueDate < asOf)
16	    .map((inv) => ({
17	      number: inv.number,
18	      customerId: inv.customerId,
19	      dueDate: inv.dueDate,
20	      daysOverdue: daysBetween(inv.dueDate, asOf),
21	      due: balanceDue(inv),
22	    }))
23	    .sort((a, b) => b.daysOverdue - a.daysOverdue);
24	}
25	
26	/**
27	 * Generate a VAT summary for invoices.
28	 * @param {Array<{ status: string, lines: Array<{ qty: number, unitPrice: number, vatRate: number, discountPercent?: number }> }>} invoices
29	 * @returns {Array<{ rate: number, base: number, vat: number }>} one entry per VAT rate, sorted by rate descending (high to low)
30	 */
31	export function vatSummary(invoices) {
32	  const vatMap = {};
33	
34	  invoices
35	    .filter((inv) => inv.status === 'issued' || inv.status === 'partially_paid' || inv.status === 'paid')
36	    .forEach((inv) => {
37	      inv.lines.forEach((line) => {
38	        const rate = line.vatRate;
39	        const base = lineTotal(line) - lineDiscount(line);
40	        const vat = lineVAT(line);
41	
42	        if (!vatMap[rate]) {
43	          vatMap[rate] = { rate, base: 0, vat: 0 };
44	        }
45	        vatMap[rate].base += base;
46	        vatMap[rate].vat += vat;
47	      });
48	    });
49	
50	  return Object.values(vatMap).sort((a, b) => b.rate - a.rate);
51	}
52	
