import { daysBetween } from './dates.js';
import { balanceDue } from './payments.js';
import { lineTotal, lineDiscount, lineVAT } from './invoices.js';
import { roundCents } from './money.js';

/**
 * Get all invoices that are overdue as of a given date.
 * @param {Array<{ number: string, customerId: string, status: string, dueDate: string, lines: Array, payments?: Array<{ amount: number, date: string }> }>} invoices
 * @param {string} asOf - YYYY-MM-DD format, cutoff date
 * @returns {Array<{ number: string, customerId: string, dueDate: string, daysOverdue: number, due: number }>} sorted by daysOverdue descending (most overdue first)
 */
export function overdueInvoices(invoices, asOf) {
  return invoices
    .filter((inv) => (inv.status === 'issued' || inv.status === 'partially_paid'))
    .filter((inv) => inv.dueDate < asOf)
    .map((inv) => ({
      number: inv.number,
      customerId: inv.customerId,
      dueDate: inv.dueDate,
      daysOverdue: daysBetween(inv.dueDate, asOf),
      due: balanceDue(inv),
    }))
    .sort((a, b) => b.daysOverdue - a.daysOverdue);
}

/**
 * Generate a VAT summary for invoices.
 * @param {Array<{ status: string, lines: Array<{ qty: number, unitPrice: number, vatRate: number, discountPercent?: number }> }>} invoices
 * @returns {Array<{ rate: number, base: number, vat: number }>} one entry per VAT rate, sorted by rate descending (high to low)
 */
export function vatSummary(invoices) {
  const vatMap = {};

  invoices
    .filter((inv) => inv.status === 'issued' || inv.status === 'partially_paid' || inv.status === 'paid')
    .forEach((inv) => {
      inv.lines.forEach((line) => {
        const rate = line.vatRate;
        const base = lineTotal(line) - lineDiscount(line);
        const vat = lineVAT(line);

        if (!vatMap[rate]) {
          vatMap[rate] = { rate, base: 0, vat: 0 };
        }
        vatMap[rate].base += base;
        vatMap[rate].vat += vat;
      });
    });

  return Object.values(vatMap).sort((a, b) => b.rate - a.rate);
}

/**
 * Calculate late fee for an invoice.
 * @param {{ dueDate: string, status: string, payments?: Array<{ amount: number, date: string }>, lines: Array }} invoice
 * @param {string} asOf - YYYY-MM-DD format, cutoff date
 * @returns {number} late fee in cents (0.04% per day overdue), or 0 if not overdue
 */
export function lateFee(invoice, asOf) {
  const daysOverdue = daysBetween(invoice.dueDate, asOf);
  if (daysOverdue <= 0) {
    return 0;
  }
  const due = balanceDue(invoice);
  return roundCents(due * 0.0004 * daysOverdue);
}

